let state = {
  mentors: [],
  activeCategory: 'all',
  searchQuery: ''
};

function loadState() {
  try {
    const saved = localStorage.getItem('mentor_search_state');
    if (saved) {
      const parsed = JSON.parse(saved);
      state.searchQuery = parsed.searchQuery || '';
      state.activeCategory = parsed.activeCategory || 'all';
    }
  } catch (e) {
    console.warn('Failed to load local state', e);
  }
  state.mentors = EXAMPLE_MENTORS;
}

function saveState() {
  try {
    localStorage.setItem('mentor_search_state', JSON.stringify({
      searchQuery: state.searchQuery,
      activeCategory: state.activeCategory
    }));
  } catch (e) {
    console.warn('Failed to save local state', e);
  }
}

function escapeHtml(text) {
  const div = document.createElement('div');
  div.textContent = text;
  return div.innerHTML;
}

function renderMentorCard(mentor) {
  const card = document.createElement('article');
  card.className = 'mentor-card';
  card.dataset.id = mentor.id;

  const header = document.createElement('div');
  header.className = 'card-header';

  const img = document.createElement('img');
  img.src = mentor.avatar;
  img.alt = mentor.name + ' 프로필';
  img.className = 'avatar';

  const info = document.createElement('div');
  info.className = 'mentor-info';

  const name = document.createElement('h2');
  name.textContent = mentor.name;

  const role = document.createElement('p');
  role.textContent = mentor.role;

  info.appendChild(name);
  info.appendChild(role);
  header.appendChild(img);
  header.appendChild(info);

  const metaContainer = document.createElement('div');
  metaContainer.className = 'metadata';

  const cert = document.createElement('span');
  cert.className = 'certification';
  cert.style.color = mentor.certification.color;
  cert.textContent = mentor.certification.text;

  const emp = document.createElement('span');
  emp.className = 'employer';
  emp.style.color = mentor.employer.color;
  emp.textContent = mentor.employer.text;

  metaContainer.appendChild(cert);
  metaContainer.appendChild(emp);

  const desc = document.createElement('p');
  desc.className = 'description';
  desc.textContent = mentor.description;

  const footer = document.createElement('div');
  footer.className = 'card-footer';

  const favBtn = document.createElement('button');
  favBtn.type = 'button';
  favBtn.className = 'fav-btn';
  favBtn.setAttribute('aria-label', mentor.name + ' 마음에 넣기');
  favBtn.innerHTML = '<img src="assets/icons/Heart.svg" alt="" width="20" height="20">';

  footer.appendChild(favBtn);

  card.appendChild(header);
  card.appendChild(metaContainer);
  card.appendChild(desc);
  card.appendChild(footer);

  return card;
}

function renderMentors() {
  const list = document.getElementById('mentor-list');
  if (!list) return;

  list.innerHTML = '';

  const filtered = state.mentors.filter(m => {
    const matchesCategory = state.activeCategory === 'all' || 
      m.role.includes(state.activeCategory === 'design' ? '디자인' : state.activeCategory === 'dev' ? '개발' : state.activeCategory === 'marketing' ? '마케팅' : '');
    const matchesSearch = !state.searchQuery || 
      m.name.includes(state.searchQuery) || 
      m.role.includes(state.searchQuery);
    return matchesCategory && matchesSearch;
  });

  filtered.forEach(m => {
    list.appendChild(renderMentorCard(m));
  });
}

